 {screen === 'analytics' && <><div className="page-heading"><div><h1>{tr('Твой прогресс в деталях', 'Сенің нәтижең толық')}</h1><p>{tr('Считаем самостоятельные решения. Полоска показывает учебную активность, а не вероятность знания. Подтверждение требует новой отложенной проверки и утверждённой преподавателем рубрики; для текущего банка рубрики ещё проверяются.', 'Өздік шешімдерді есептейміз. Жолақ білім ықтималдығын емес, оқу белсенділігін көрсетеді. Растау үшін жаңа кейінгі тексеру мен мұғалім бекіткен өлшемдер қажет; қазіргі қордың өлшемдері әлі тексерілуде.')}</p></div><a className="secondary" href="/api/history/export"><Download size={17}/>{tr('Скачать всю историю', 'Толық тарихты жүктеу')}</a></div><div className="analytics-stats">{[[tracks[track][lang], trackStats.attempts], [tr('Верно без отмеченной помощи', 'Белгіленген көмексіз дұрыс'), trackStats.independentCorrect], [tr('Освоено тем', 'Меңгерілген тақырыптар'), trackMastered], [tr('Игровой уровень', 'Ойын деңгейі'), Math.floor((state?.xp ?? 0) / 250) + 1]].map(([l, v]) => <div className="panel" key={l}><small>{l}</small><strong>{v}</strong></div>)}</div><LearningEvidence data={state?.statistics?.evidence} track={track} lang={lang} titles={Object.fromEntries(curriculum.map(t=>[t.id,t.title]))} onPractice={id=>void loadPractice(id)} onExams={()=>navigate('exams')}/><section className="panel progress-by-topic"><h2>{tr('Навыки по направлениям', 'Бағыттар бойынша дағдылар')}</h2><div className="track-tabs">{(Object.keys(tracks) as (keyof typeof tracks)[]).map(t => <button aria-pressed={track === t} className={track === t ? 'selected' : ''} key={t} onClick={() => changeTrack(t)}>{tracks[t][lang]}</button>)}</div>{filtered.map(t => <button className="skill-row" key={t.id} onClick={() => openLesson(t.id)}><span>{t.title[lang]}</span><div className="progress-track"><span style={{ width: `${percent(t.id)}%` }}/></div><strong>{percent(t.id)}%</strong><span className="muted">{progress[t.id]?.needsRecovery ? tr('Нужно уточнить', 'Нақтылау керек') : progress[t.id]?.mastered ? tr('Освоено', 'Меңгерілді') : progress[t.id]?.masteryPending ? tr('Ожидает подтверждения', 'Растауды күтуде') : progress[t.id]?.independent ? tr('Закрепляем', 'Бекітеміз') : tr('Начать', 'Бастау')}</span><ChevronRight size={16}/></button>)}</section>{user&&!activeExam&&<HistoryList key={`attempts:${user.id}:${state?.history?.attempts??0}`} kind="attempts" lang={lang} topicTitles={Object.fromEntries(curriculum.map(t=>[t.id,t.title]))}/>}</>}
 {screen === 'achievements'  && <><div className="page-heading"><div><h1>{tr('Твои маленькие победы', 'Сенің кішкентай жеңістерің')}</h1><p>{tr('Опыт мотивирует. Освоение показывает, что ты умеешь.', 'Тәжірибе ынталандырады. Меңгеру не істей алатыныңды көрсетеді.')}</p></div></div><div className="level-panel"><span className="achievement-icon"><Trophy size={35}/></span><div><small>{tr('Игровой уровень', 'Ойын деңгейі')}</small><h2>{Math.floor((state?.xp ?? 0) / 250) + 1} · {tr('Исследователь', 'Зерттеуші')}</h2><p>{state?.xp ?? 0} XP · {250 - (state?.xp ?? 0) % 250} {tr('до следующего уровня', 'келесі деңгейге дейін')}</p></div><div className="level-mastery"><strong>{mastered}</strong><span>{tr('тем освоено', 'тақырып меңгерілді')}</span></div></div><div className="achievement-grid">{[{ title: tr('Первый шаг', 'Алғашқы қадам'), text: tr('Заверши диагностику', 'Диагностиканы аяқта'), done: state?.diagnostics?.length > 0, Icon: Target }, { title: tr('Сам себе помощник', 'Өзіңе көмекші'), text: tr('Реши 3 новые задачи без подсказок', '3 жаңа есепті кеңессіз шеш'), done: Object.values(progress).reduce((sum: number, p: Data) => sum + (p.independent ?? 0), 0) >= 3, Icon: PenLine }, { title: tr('Ошибка в прошлом', 'Қате артта қалды'), text: tr('Реши задачу при повторении', 'Қайталауда есепті шеш'), done: state?.reviews?.some((r: Data) => r.completed), Icon: RotateCcw }, { title: tr('Крепкий фундамент', 'Берік негіз'), text: tr('Подтверди освоение первой темы', 'Алғашқы тақырыпты меңгеруді раста'), done: mastered > 0, Icon: BookOpen }, { title: tr('Готов к формату', 'Форматқа дайын'), text: tr('Заверши пробный экзамен', 'Сынақ емтиханын аяқта'), done: state?.exams?.length > 0, Icon: ClipboardCheck }, { title: tr('Возвращение к сложному', 'Қиынға қайта оралу'), text: tr('Реши самостоятельно после двух ошибок в одном навыке', 'Бір дағдыда екі қатеден кейін өз бетіңмен шеш'), done: state?.statistics?.returnedToChallenge ?? returnedToChallenge(attempts), Icon: Flame }].map(a => <article className={`panel achievement-card ${a.done ? 'unlocked' : 'locked'}`} key={a.title}><span className="achievement-icon"><a.Icon size={30}/></span><h3>{a.title}</h3><p>{a.text}</p><span className="small-chip">{a.done ? <Check size={13}/> : <LockKeyhole size={13}/>} {a.done ? tr('Получено', 'Алынды') : tr('Впереди', 'Алда')}</span></article>)}</div></>}
 {screen === 'visuals' && <><div className="page-heading"><div><span className="date-line">{tr('Измени. Заметь. Сделай вывод.', 'Өзгерт. Байқа. Қорытынды жаса.')}</span><h1>{tr('Математика в движении', 'Қозғалыстағы математика')}</h1><p>{tr('Проверь идеи — от дробей до пространственных тел.', 'Идеяларды тексер — бөлшектерден кеңістіктегі денелерге дейін.')}</p></div></div><MathVisuals lang={lang}/></>}
 {screen === 'achievements' && <section className="panel ranking-panel"><div className="section-heading"><h2>{tr('Рейтинг по желанию', 'Қалауың бойынша рейтинг')}</h2><button className="text-button" onClick={() => navigate('settings')}>{tr('Участие и приватность', 'Қатысу және құпиялық')}<ArrowRight size={16}/></button></div><p>{state?.preferences?.leaderboard ? tr('Ты участвуешь. Опыт и математическое освоение показаны отдельно.', 'Сен қатысасың. Тәжірибе мен математиканы меңгеру бөлек көрсетіледі.') : tr('Участие выключено. Твои данные не публикуются в рейтинге.', 'Қатысу өшірулі. Деректерің рейтингте жарияланбайды.')}</p>{leaderboard === null && user ? <p className="muted">{tr('Загружаем добровольный рейтинг…', 'Ерікті рейтинг жүктелуде…')}</p> : leaderboard?.entries?.length ? <div className="ranking-scroll"><table><thead><tr><th>#</th><th>{tr('Ученик', 'Оқушы')}</th><th>XP</th><th>{tr('Освоено', 'Меңгерілді')}</th></tr></thead><tbody>{leaderboard.entries.map((entry: Data) => <tr key={entry.rank}><td>{entry.rank}</td><td>{entry.name}{entry.self ? tr(' · ты', ' · сен') : ''}{entry.testIdentity ? tr(' (тест)', ' (сынақ)') : ''}</td><td>{entry.xp}</td><td>{entry.mastered}</td></tr>)}</tbody></table></div> : <div className="mint-note">{tr('Пока нет участников. Здесь появятся только реальные добровольные результаты.', 'Әзірге қатысушы жоқ. Мұнда тек нақты ерікті нәтижелер пайда болады.')}</div>}</section>}
