function categoryName(s: string, l: Lang) { const n: Data = { unconfirmed: { ru: 'Причина требует уточнения', kk: 'Себебін нақтылау керек' }, unknown: { ru: 'Причина ещё не установлена', kk: 'Себебі әлі анықталмады' }, sign: { ru: 'Ошибка в знаках', kk: 'Таңба қатесі' }, calculation: { ru: 'Ошибка вычисления', kk: 'Есептеу қатесі' }, understanding: { ru: 'Непонимание правила', kk: 'Ережені түсінбеу' }, method: { ru: 'Выбор метода', kk: 'Әдіс таңдау' }, reading: { ru: 'Чтение условия', kk: 'Шартты оқу' } }; return n[s]?.[l] ?? s; }
