function calendarWeek() { const parts = Object.fromEntries(new Intl.DateTimeFormat("en", { timeZone: "Asia/Qyzylorda", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date()).filter(p => p.type !== "literal").map(p => [p.type, p.value])); const today = new Date(`${parts.year}-${parts.month}-${parts.day}T12:00:00Z`); const start = new Date(today); start.setUTCDate(today.getUTCDate() - (today.getUTCDay() + 6) % 7); return Array.from({ length: 7 }, (_, i) => { const d = new Date(start); d.setUTCDate(start.getUTCDate() + i); return { key: d.toISOString().slice(0, 10), day: d.getUTCDate(), today: d.getUTCDate() === today.getUTCDate() }; }); }
